_choice_im_color() {
    magick -list color 2>/dev/null | _argc_util_transform_table 'Name;Color' '\t'
}

_choice_im_define() {
    if [[ "${ARGC_CWORD:-}" == *:* ]]; then
        return 0
    fi
    magick -list format 2>/dev/null |
        _argc_util_transform_table 'Format' |
        gawk '{ gsub(/^[ \t]+|[ \t]+$/, ""); sub(/\*$/, ""); if ($0 != "") print tolower($0) }' |
        _argc_util_transform suffix=: nospace
}

_choice_im_list() {
    local list_type= slot=-1
    case "${argc__option:-}" in
    argc_list) list_type=list ;;
    argc_alpha) list_type=alpha ;;
    argc_colorspace | argc_quantize) list_type=colorspace ;;
    argc_compose) list_type=compose ;;
    argc_compress) list_type=compress ;;
    argc_filter) list_type=filter ;;
    argc_gravity) list_type=gravity ;;
    argc_type) list_type=type ;;
    argc_interlace) list_type=interlace ;;
    argc_dither) list_type=dither ;;
    argc_dispose) list_type=dispose ;;
    argc_direction) list_type=direction ;;
    argc_endian) list_type=endian ;;
    argc_illuminant) list_type=illuminant ;;
    argc_intensity | argc_grayscale) list_type=intensity ;;
    argc_intent) list_type=intent ;;
    argc_interpolate) list_type=interpolate ;;
    argc_preview) list_type=preview ;;
    argc_stretch) list_type=stretch ;;
    argc_style) list_type=style ;;
    argc_units) list_type=units ;;
    argc_virtual_pixel) list_type=virtual-pixel ;;
    argc_weight) list_type=weight ;;
    argc_debug) list_type=debug ;;
    argc_channel) list_type=channel ;;
    argc_layers) list_type=layers ;;
    argc_auto_threshold) list_type=autothreshold ;;
    argc_evaluate_sequence) list_type=evaluate ;;
    argc_complex) list_type=complex ;;
    argc_evaluate) list_type=evaluate slot=0 ;;
    argc_distort) list_type=distort slot=0 ;;
    argc_statistic) list_type=statistic slot=0 ;;
    argc_function) list_type=function slot=0 ;;
    argc_morphology) list_type=morphology slot=0 ;;
    argc_sparse_color) list_type=sparse-color slot=0 ;;
    *) return 0 ;;
    esac
    if [[ $slot -ge 0 ]] && ! _helper_im_value_slot "$slot"; then
        return 0
    fi
    magick -list "$list_type" 2>/dev/null
}

_helper_im_value_slot() {
    local -n values="$argc__option"
    [[ ${#values[@]} -eq $(($1 + 1)) ]]
}
